use substrate_rs::p3_learning::{LearningProposal,P3ChangeKind,P3ProposalStatus};
#[test] fn native_proposal_never_has_approved_state() { let p=LearningProposal{proposal_digest:"sha256:1".repeat(1),parent_snapshot_digest:"sha256:2".repeat(1),mutable_artifact_path:"mutable-agent/rules".into(),mutable_artifact_digest:"sha256:3".into(),change_kind:P3ChangeKind::Rule,patch_digest:"sha256:4".into(),provenance_refs:vec![],evidence_refs:vec![],rollback_snapshot_digest:"sha256:5".into(),status:P3ProposalStatus::Proposed}; assert!(p.proposed()); assert_eq!(p.reject().status,P3ProposalStatus::Rejected); }
